package cn.guihualab.liveai;
import android.Manifest;import android.app.Application;import android.content.Context;import android.media.*;import android.os.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.shadow.api.Shadow;import org.robolectric.util.ReflectionHelpers;import java.util.*;import static org.junit.Assert.*;import static org.robolectric.Shadows.shadowOf;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34,shadows={NativeInputSwitchTest.DeviceShadow.class,NativeInputSwitchTest.RecordShadow.class,NativeInputSwitchTest.TrackShadow.class})
public class NativeInputSwitchTest {
 @Implements(AudioDeviceInfo.class) public static class DeviceShadow{int id,type;boolean source;String name,address;@Implementation public int getId(){return id;}@Implementation public int getType(){return type;}@Implementation public boolean isSource(){return source;}@Implementation public boolean isSink(){return !source;}@Implementation public CharSequence getProductName(){return name;}@Implementation public String getAddress(){return address;}}
 @Implements(AudioRecord.class) public static class RecordShadow{AudioDeviceInfo actual,preferred;boolean accept=true;int requests;@Implementation public AudioDeviceInfo getRoutedDevice(){return actual;}@Implementation public boolean setPreferredDevice(AudioDeviceInfo device){preferred=device;requests++;return accept;}@Implementation public void startRecording(){}@Implementation public void stop(){}@Implementation public int read(byte[] data,int offset,int size,int mode){Arrays.fill(data,offset,offset+size,(byte)20);return size;}}
 @Implements(AudioTrack.class) public static class TrackShadow{@Implementation public boolean setPreferredDevice(AudioDeviceInfo device){return true;}@Implementation public AudioDeviceInfo getRoutedDevice(){return null;}}
 private AudioDeviceInfo device(int id,int type,boolean source,String name,String address){AudioDeviceInfo d=Shadow.newInstanceOf(AudioDeviceInfo.class);DeviceShadow s=Shadow.extract(d);s.id=id;s.type=type;s.source=source;s.name=name;s.address=address;return d;}
 private NativeAudio audio;private AudioRecord record;private RecordShadow recorder;private Application context;private AudioDeviceInfo phone,bt,btInput;private final List<byte[]> uploaded=new ArrayList<>();
 @Before public void setup(){context=(Application)RuntimeEnvironment.getApplication();shadowOf(context).grantPermissions(Manifest.permission.RECORD_AUDIO,Manifest.permission.BLUETOOTH_CONNECT);phone=device(10,15,true,"Phone","bottom");bt=device(20,7,false,"Headset","bt");btInput=device(21,7,true,"Headset","bt");AudioManager manager=context.getSystemService(AudioManager.class);shadowOf(manager).setInputDevices(List.of(phone));shadowOf(manager).setAvailableCommunicationDevices(List.of(bt));record=Shadow.newInstanceOf(AudioRecord.class);recorder=Shadow.extract(record);recorder.actual=phone;audio=new NativeAudio(context,new NativeAudio.Listener(){public void microphone(byte[] bytes){uploaded.add(bytes);if(uploaded.size()==1){recorder.actual=btInput;ReflectionHelpers.callInstanceMethod(audio,"reportRoute");}if(uploaded.size()>=3)ReflectionHelpers.setField(audio,"running",false);}public void acknowledge(PlaybackLedger.Ack ack){}public void stopped(String r,String t,long m){}public void routing(String i,String o,int t){}public void error(String text){throw new AssertionError(text);}});ReflectionHelpers.setField(audio,"recorder",record);ReflectionHelpers.setField(audio,"track",Shadow.newInstanceOf(AudioTrack.class));ReflectionHelpers.setField(audio,"running",true);}
 @After public void cleanup(){audio.close();}
 @Test public void lateBluetoothSourceIsPreferredAfterCommunicationRequestAndCaptureWaitsForActualRouting() throws Exception {
  audio.input("comm:"+AudioInputs.Device.of(bt).key);shadowOf(Looper.getMainLooper()).idle();assertEquals(bt,context.getSystemService(AudioManager.class).getCommunicationDevice());assertEquals(0,recorder.requests);assertEquals("pending",audio.inputs().getString("status"));assertFalse(audio.inputs().getBoolean("uploadEnabled"));
  shadowOf(context.getSystemService(AudioManager.class)).setInputDevices(List.of(phone,btInput));shadowOf(Looper.getMainLooper()).idleFor(java.time.Duration.ofMillis(250));assertEquals(btInput,recorder.preferred);assertTrue((int)ReflectionHelpers.getField(audio,"inputEpoch")>0);assertFalse(audio.inputs().getBoolean("uploadEnabled"));
  ReflectionHelpers.callInstanceMethod(audio,"captureLoop");assertEquals(3,uploaded.size());assertArrayEquals(new byte[640],uploaded.get(0));assertFalse(Arrays.equals(new byte[640],uploaded.get(1)));assertTrue((boolean)ReflectionHelpers.getField(audio,"inputConfirmed"));
 }
 @Test public void platformRejectingTheInputIsReportedAndPhoneCaptureRemainsBlocked() throws Exception {
  shadowOf(context.getSystemService(AudioManager.class)).setInputDevices(List.of(phone,btInput));recorder.accept=false;audio.input("comm:"+AudioInputs.Device.of(bt).key);shadowOf(Looper.getMainLooper()).idle();JSONObject state=audio.inputs();assertEquals("failed",state.getString("status"));assertEquals(15,state.getInt("actualType"));assertFalse(state.getBoolean("uploadEnabled"));assertTrue(state.getString("message").contains("系统拒绝"));
 }
}
